// Interaction smoke test — Civil survey / GIS import (mục 3). Fresh profile, dev server :5173.
// Uses the SYNTHETIC fixtures in qa/fixtures/civil (generated by tools/make-survey-fixtures.mjs).
import { chromium } from 'playwright'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

const FX = new URL('../../qa/fixtures/civil/', import.meta.url).pathname
const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 1586, height: 992 }, acceptDownloads: true })
ctx.setDefaultTimeout(6000)
const page = await ctx.newPage()
const errors = []
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()))
page.on('pageerror', (e) => errors.push(String(e)))
const results = []
const step = async (name, fn) => {
  try { await fn(); results.push(['PASS', name]) } catch (e) { results.push(['FAIL', name + ' — ' + e.message.split('\n')[0]]) }
}
await page.addInitScript(() => {
  if (!sessionStorage.getItem('seeded')) {
    localStorage.setItem('thcad.settings', JSON.stringify({ state: { language: 'en' }, version: 1 }))
    sessionStorage.setItem('seeded', '1')
  }
})
await page.goto((process.env.THCAD_UI ?? 'http://127.0.0.1:5173') + '/#/civil', { waitUntil: 'networkidle' })
const more = async (item) => {
  await page.getByRole('button', { name: 'More Tools', exact: true }).click()
  await page.getByRole('menuitem', { name: item }).click()
}
const dialog = () => page.getByTestId('survey-import')
const firstRow = () => page.getByRole('table', { name: 'Earthwork Quantities' }).getByRole('row').nth(1).innerText()
const egPath = () => page.locator('svg path[class*="_eg_"]').first().getAttribute('d')
let eg0, row0

await step('More Tools → Import survey opens the dialog; a CSV (PNEZD with header) is previewed with its statistics', async () => {
  eg0 = await egPath()
  row0 = await firstRow()
  await more('Import survey / GIS…')
  await dialog().locator('input[type=file]').setInputFiles(FX + 'canal_survey_SYNTHETIC.csv')
  const d = dialog()
  await d.getByText('1,404', { exact: true }).waitFor()
  assert.equal(await d.getByLabel('Column order').inputValue(), 'PNEZD')
  assert.match(await d.innerText(), /2,734/) // triangles
  assert.match(await d.innerText(), /8\.48 ha/)
  assert.match(await d.innerText(), /6\.325 … 8\.434 m/)
  assert.match(await d.innerText(), /Alignment in file\s+none/)
})

await step('Import: the plan shows the real surface (no DEMO badge); without an alignment the ground stays the sample profile and the user is told', async () => {
  await page.getByRole('button', { name: 'Import', exact: true }).click()
  await page.getByTestId('survey-plan').waitFor()
  assert.equal(await page.getByText(/^DEMO imagery/).count(), 0)
  assert.match(await page.getByTestId('survey-plan').innerText(), /Survey · canal_survey_SYNTHETIC\.csv · 1,404 pts · 2,734 tri/)
  await page.getByText(/No alignment yet/).first().waitFor()
  assert.equal(await egPath(), eg0)
})

await step('LandXML with an alignment: existing ground now comes from the surface along CANAL-01; profile, section and earthwork change', async () => {
  await more('Import survey / GIS…')
  await dialog().locator('input[type=file]').setInputFiles(FX + 'canal_survey_SYNTHETIC.xml')
  await dialog().getByText(/CANAL-01 · 619\.99 m/).waitFor()
  assert.ok(await dialog().getByLabel(/Use the alignment from the file/).isChecked())
  await page.getByRole('button', { name: 'Import', exact: true }).click()
  await page.getByTestId('survey-plan').waitFor()
  assert.notEqual(await egPath(), eg0)
  assert.notEqual(await firstRow(), row0)
  assert.equal(await page.getByTestId('section-survey-ground').count(), 1)
})

await step('Layers panel: survey statistics, existing ground "survey surface along the alignment"; contour interval is editable', async () => {
  await page.getByRole('tab', { name: 'Layers' }).click()
  const p = page.getByTestId('survey-panel')
  assert.match(await p.innerText(), /canal_survey_SYNTHETIC\.xml/)
  assert.match(await p.innerText(), /survey surface along the alignment/)
  assert.match(await p.innerText(), /8\.48 ha/)
})

await step('exports: points CSV, contours DXF and LandXML (re-imported: same points and alignment length)', async () => {
  const get = async (label) => {
    await page.getByRole('button', { name: 'Export', exact: true }).click()
    const [dl] = await Promise.all([page.waitForEvent('download'), page.getByRole('menuitem', { name: label }).click()])
    return readFileSync(await dl.path(), 'utf8')
  }
  const csv = await get('Survey points (CSV)')
  assert.equal(csv.trim().split(/\r?\n/).length, 1405)
  const dxf = await get('Contours (DXF)')
  assert.match(dxf, /C-TOPO-MAJR/)
  assert.ok((dxf.match(/\nPOLYLINE\r?\n/g) ?? []).length >= 10)
  const xml = await get('Surface + alignment (LandXML)')
  assert.match(xml, /<Faces>/)
  const back = await page.evaluate(async (x) => {
    const m = await import('/src/civil/survey.ts')
    const s = m.parseLandXml('roundtrip.xml', x)
    const t = await import('/src/civil/tin.ts')
    return { n: s.x.length, faces: s.faces.length / 3, L: t.polyLength(s.alignment) }
  }, xml)
  assert.equal(back.n, 1404)
  assert.equal(back.faces, 2734)
  assert.ok(Math.abs(back.L - 619.99) < 0.01)
})

await step('click on the alignment picks the nearest 20 m station; ⌘Z undoes the import (back to the CSV-only survey)', async () => {
  const box = await page.getByTestId('survey-plan').boundingBox()
  // the station marker follows the selection: pick by clicking the centre of the plan (near the alignment), any station change counts
  const before = await page.getByRole('img', { name: /^Cross section/ }).first().getAttribute('aria-label')
  await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2)
  const after = await page.getByRole('img', { name: /^Cross section/ }).first().getAttribute('aria-label')
  assert.ok(before && after)
  await page.locator('body').click({ position: { x: 1180, y: 128 } })
  await page.keyboard.press('Meta+z')
  await page.getByText(/Survey · canal_survey_SYNTHETIC\.csv/).waitFor()
})

await step('Draw alignment: clicks + double-click make a new centre line; the ground is sampled along it', async () => {
  await more('Draw alignment on the plan')
  await page.getByText(/Click to add centre-line points/).waitFor()
  const box = await page.getByTestId('survey-plan').boundingBox()
  const y = box.y + box.height * 0.55
  await page.mouse.click(box.x + box.width * 0.3, y)
  await page.mouse.click(box.x + box.width * 0.5, y - 10)
  await page.mouse.dblclick(box.x + box.width * 0.7, y - 30)
  await page.getByText(/Alignment drawn: \d+\.\d m/).first().waitFor()
  await page.getByRole('tab', { name: 'Layers' }).click()
  assert.match(await page.getByTestId('survey-panel').innerText(), /survey surface along the alignment/)
})

await step('GeoJSON (WGS84) is projected to UTM 48N and gives the same surface; DXF survey points + C-ALIGN polyline too', async () => {
  for (const [f, crs] of [['canal_survey_SYNTHETIC.geojson', /WGS84 → UTM 48N/], ['canal_survey_SYNTHETIC.dxf', /drawing units/]]) {
    await more('Import survey / GIS…')
    await dialog().locator('input[type=file]').setInputFiles(FX + f)
    await dialog().getByText('2,734').waitFor()
    assert.match(await dialog().innerText(), crs)
    await page.getByRole('button', { name: 'Import', exact: true }).click()
    await page.getByTestId('survey-plan').waitFor()
  }
})

await step('Shapefile set (.shp + .dbf + .prj, geographic → UTM 48N): same surface; then a centre-line shapefile sets the alignment', async () => {
  await more('Remove survey')
  await more('Import survey / GIS…')
  await dialog().locator('input[type=file]').setInputFiles(['shp', 'dbf', 'prj'].map((e) => FX + 'canal_points_SYNTHETIC.' + e))
  await dialog().getByText('2,734').waitFor()
  assert.match(await dialog().innerText(), /GCS_WGS_1984 → UTM 48N/)
  assert.match(await dialog().innerText(), /Alignment in file\s+none/)
  await page.getByRole('button', { name: 'Import', exact: true }).click()
  await page.getByText(/Survey · canal_points_SYNTHETIC\.shp · 1,404 pts/).waitFor()
  await more('Import survey / GIS…')
  await dialog().locator('input[type=file]').setInputFiles(['shp', 'dbf', 'prj'].map((e) => FX + 'canal_centreline_SYNTHETIC.' + e))
  await dialog().getByText(/Alignment only \(CANAL-01, 619\.99 m\)/).waitFor()
  await page.getByRole('button', { name: 'Import', exact: true }).click()
  await page.getByText(/Alignment drawn: 620\.0 m/).first().waitFor()
  await page.getByRole('tab', { name: 'Layers' }).click()
  assert.match(await page.getByTestId('survey-panel').innerText(), /survey surface along the alignment/)
})

await step('a file without elevations is refused with a clear message', async () => {
  await more('Import survey / GIS…')
  await dialog().locator('input[type=file]').setInputFiles({ name: 'bad.csv', mimeType: 'text/csv', buffer: Buffer.from('a,b\n1,2\n') })
  await dialog().getByRole('alert').waitFor()
  assert.match(await dialog().getByRole('alert').innerText(), /Cannot read this file: only 0 point/)
  assert.ok(await page.getByRole('button', { name: 'Import', exact: true }).isDisabled())
  await page.getByRole('button', { name: 'Cancel' }).click()
})

await step('Remove survey: DEMO imagery and the sample ground come back', async () => {
  await more('Remove survey')
  await page.getByText(/^DEMO imagery/).waitFor()
  assert.equal(await page.getByTestId('survey-plan').count(), 0)
})

await page.screenshot({ path: new URL('../../qa/survey_after_remove.png', import.meta.url).pathname })
const bad = errors.filter((e) => !/favicon|DevTools/.test(e))
results.push([bad.length ? 'FAIL' : 'PASS', `no console errors${bad.length ? ': ' + bad.slice(0, 3).join(' | ') : ''}`])
for (const [r, n] of results) console.log(r.padEnd(5), n)
console.log(`\n${results.filter((r) => r[0] === 'PASS').length}/${results.length} passed`)
await browser.close()
